import re
from collections import Counter

import pytesseract
from PIL import Image
from openpyxl import Workbook


IMG_DIR = "/app/workspace/dataset/img"
OUTPUT_PATH = "/app/workspace/stat_ocr.xlsx"


PRIORITY_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

STRICT_EXCLUSIONS = ["SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED"]
FALLBACK_EXCLUSIONS = ["SUBTOTAL", "SUB TOTAL", "DISCOUNT", "CHANGE", "CASH TENDERED"]

SUMMARY_REGEX = re.compile(r"(GST|GS1|G\$T|ST|TAX)\s*SUMMARY", re.IGNORECASE)

AMOUNT_REGEX = re.compile(
    r"(?<![\d.,])(?:\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2}|\d+,\d{2})(?![\d])"
)

DATE_REGEX = re.compile(r"\b(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})\b")


def normalize_line(line: str) -> str:
    return re.sub(r"[-_]", " ", line.upper())


def find_last_amount(line: str):
    matches = list(AMOUNT_REGEX.finditer(line))
    if not matches:
        return None
    s = matches[-1].group()
    if "," in s and "." in s:
        return float(s.replace(",", ""))
    if "," in s:
        return float(s.replace(",", "."))
    return float(s)


def truncate_at_summary(text: str):
    lines = text.split("\n")
    for i, line in enumerate(lines):
        if SUMMARY_REGEX.search(line):
            return lines[:i]
    return lines


def _search_total(lines, exclusions):
    for priority in PRIORITY_KEYWORDS:
        matches = []
        for line in lines:
            norm = normalize_line(line)
            if any(e in norm for e in exclusions):
                continue
            if not any(kw in norm for kw in priority):
                continue
            amt = find_last_amount(line)
            if amt is not None:
                matches.append(amt)
        if matches:
            return matches[-1]
    return None


def extract_total_from_text(text: str):
    lines = truncate_at_summary(text)
    total = _search_total(lines, STRICT_EXCLUSIONS)
    if total is not None:
        return total
    return _search_total(lines, FALLBACK_EXCLUSIONS)


def extract_total(ocr_texts):
    for text in ocr_texts:
        total = extract_total_from_text(text)
        if total is not None:
            return total
    return None


def parse_date_parts(d, m, y):
    d, m, y = int(d), int(m), int(y)
    if y < 100:
        y += 2000
    if not (1 <= d <= 31 and 1 <= m <= 12 and 2000 <= y <= 2099):
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_dates_from_text(text: str):
    found = []
    for m in DATE_REGEX.finditer(text):
        parsed = parse_date_parts(*m.groups())
        if parsed:
            found.append(parsed)
    return found


def extract_date(ocr_texts):
    all_dates = []
    for text in ocr_texts:
        all_dates.extend(extract_dates_from_text(text))
    if not all_dates:
        return None
    counter = Counter(all_dates)
    best_count = counter.most_common(1)[0][1]
    top = [d for d, c in counter.items() if c == best_count]
    for d in all_dates:
        if d in top:
            return d
    return None


def ocr_image(path: str):
    img = Image.open(path)
    return [
        pytesseract.image_to_string(img, config="--psm 6"),
        pytesseract.image_to_string(img, config="--psm 3"),
    ]


def format_total(value):
    if value is None:
        return None
    return f"{value:.2f}"


def main():
    files = sorted(os.listdir(IMG_DIR))
    rows = []
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        ocr_texts = ocr_image(path)
        date = extract_date(ocr_texts)
        total = extract_total(ocr_texts)
        rows.append((fname, date, format_total(total)))
        print(f"{fname}: date={date}, total={format_total(total)}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for row in rows:
        ws.append(list(row))
    wb.save(OUTPUT_PATH)
    print(f"Saved to {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
